#include <bits/stdc++.h>
using namespace std;

static const long long CAPM = 20000000LL;
static const long long CAPL = 25000000LL;

struct Item {
    string name;
    int q;
    long long v, m, l;
};

int n;
Item items[12];
long long bestVal;
int bestSol[12];
int curSol[12];
chrono::steady_clock::time_point startTime;
bool timeUp;

void checkTime() {
    auto now = chrono::steady_clock::now();
    if (chrono::duration_cast<chrono::milliseconds>(now - startTime).count() > 900)
        timeUp = true;
}

long long callCount = 0;

// Lagrangian relaxation bound: for given lambda >= 0, combine constraints
// max sum v_i * x_i  s.t.  sum (m_i + lambda * l_i) * x_i <= CAPM + lambda * CAPL, 0 <= x_i <= q_i
// This is a single-constraint knapsack => greedy fractional gives exact LP bound
// We search over lambda to find tightest (minimum) dual bound
double lagrangianBound(int idx, long long rm, long long rl, long long curVal, double lambda) {
    double cap = (double)rm + lambda * (double)rl;
    // Items sorted by v_i / (m_i + lambda * l_i) descending for this lambda
    // We need to do greedy fractional

    // Collect items from idx..n-1 with their combined weight
    struct LI {
        double ratio;
        double w;
        double maxVal;
        int q;
        long long v;
    };
    static LI lis[12];
    int cnt = 0;
    for (int i = idx; i < n; i++) {
        double w = (double)items[i].m + lambda * (double)items[i].l;
        double r = (w > 1e-12) ? (double)items[i].v / w : 1e18;
        lis[cnt++] = {r, w, (double)items[i].v * items[i].q, items[i].q, items[i].v};
    }
    // Sort by ratio descending
    sort(lis, lis + cnt, [](const LI& a, const LI& b){ return a.ratio > b.ratio; });

    double ub = (double)curVal;
    double remCap = cap;
    for (int i = 0; i < cnt; i++) {
        double totalW = lis[i].w * lis[i].q;
        if (totalW <= remCap + 1e-9) {
            ub += lis[i].maxVal;
            remCap -= totalW;
        } else {
            if (lis[i].w > 1e-12) {
                double frac = remCap / lis[i].w;
                frac = min(frac, (double)lis[i].q);
                ub += (double)lis[i].v * frac;
            } else {
                ub += lis[i].maxVal;
            }
            break;
        }
    }
    return ub;
}

double upperBound(int idx, long long rm, long long rl, long long curVal) {
    // Try several lambda values and take the minimum (tightest bound)
    // Also do the two single-constraint bounds (lambda=0 gives mass-only, lambda->inf gives volume-only)
    double best = 1e30;

    // lambda = 0: mass constraint only
    {
        double ub = lagrangianBound(idx, rm, rl, curVal, 0.0);
        best = min(best, ub);
    }

    // Large lambda: effectively volume constraint only
    {
        // volume only bound
        double ub = (double)curVal;
        double remL = (double)rl;
        struct LI { double ratio; double w; int q; long long v; };
        static LI lis[12];
        int cnt = 0;
        for (int i = idx; i < n; i++) {
            double w = (double)items[i].l;
            double r = (w > 1e-12) ? (double)items[i].v / w : 1e18;
            lis[cnt++] = {r, w, items[i].q, items[i].v};
        }
        sort(lis, lis + cnt, [](const LI& a, const LI& b){ return a.ratio > b.ratio; });
        for (int i = 0; i < cnt; i++) {
            double totalW = lis[i].w * lis[i].q;
            if (totalW <= remL + 1e-9) {
                ub += (double)lis[i].v * lis[i].q;
                remL -= totalW;
            } else {
                if (lis[i].w > 1e-12) {
                    double frac = min(remL / lis[i].w, (double)lis[i].q);
                    ub += (double)lis[i].v * frac;
                }
                break;
            }
        }
        best = min(best, ub);
    }

    // Binary search for optimal lambda
    double lo = 0.0, hi = 100.0;
    for (int iter = 0; iter < 30; iter++) {
        double m1 = lo + (hi - lo) / 3.0;
        double m2 = hi - (hi - lo) / 3.0;
        double v1 = lagrangianBound(idx, rm, rl, curVal, m1);
        double v2 = lagrangianBound(idx, rm, rl, curVal, m2);
        if (v1 < v2) {
            hi = m2;
        } else {
            lo = m1;
        }
    }
    double mid = (lo + hi) / 2.0;
    best = min(best, lagrangianBound(idx, rm, rl, curVal, mid));

    return best;
}

void solve(int idx, long long rm, long long rl, long long curVal) {
    if (timeUp) return;

    if (idx == n) {
        if (curVal > bestVal) {
            bestVal = curVal;
            memcpy(bestSol, curSol, sizeof(bestSol));
        }
        return;
    }

    if (++callCount % 10000 == 0) checkTime();
    if (timeUp) return;

    double ub = upperBound(idx, rm, rl, curVal);
    if (ub <= (double)bestVal + 0.5) return;

    long long maxByM = (items[idx].m > 0) ? rm / items[idx].m : (long long)items[idx].q;
    long long maxByL = (items[idx].l > 0) ? rl / items[idx].l : (long long)items[idx].q;
    int maxTake = (int)min({(long long)items[idx].q, maxByM, maxByL});

    for (int k = maxTake; k >= 0; k--) {
        curSol[idx] = k;
        solve(idx + 1, rm - (long long)k * items[idx].m, rl - (long long)k * items[idx].l, curVal + (long long)k * items[idx].v);
        if (timeUp) return;
    }
    curSol[idx] = 0;
}

int main(){
    startTime = chrono::steady_clock::now();
    string input((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());

    vector<pair<string, vector<long long>>> entries;
    size_t pos = 0;
    while(true) {
        pos = input.find('"', pos);
        if (pos == string::npos) break;
        size_t end = input.find('"', pos+1);
        string key = input.substr(pos+1, end-pos-1);
        pos = end+1;
        size_t br = input.find('[', pos);
        if (br == string::npos) break;
        size_t br2 = input.find(']', br);
        string arr = input.substr(br+1, br2-br-1);
        pos = br2+1;
        vector<long long> nums;
        stringstream ss(arr);
        string token;
        while(getline(ss, token, ',')) {
            long long val = 0;
            for (char c : token) if (c >= '0' && c <= '9') val = val*10 + (c-'0');
            nums.push_back(val);
        }
        if (nums.size() == 4) entries.push_back({key, nums});
    }

    n = entries.size();
    map<string,int> nameToIdx;
    for (int i = 0; i < n; i++) {
        items[i].name = entries[i].first;
        items[i].q = (int)entries[i].second[0];
        items[i].v = entries[i].second[1];
        items[i].m = entries[i].second[2];
        items[i].l = entries[i].second[3];
        nameToIdx[items[i].name] = i;
    }

    // Sort by value density descending
    sort(items, items+n, [](const Item& a, const Item& b){
        double da = (double)a.v / max(a.m * 25.0, a.l * 20.0);
        double db = (double)b.v / max(b.m * 25.0, b.l * 20.0);
        return da > db;
    });

    bestVal = -1;
    memset(bestSol, 0, sizeof(bestSol));
    memset(curSol, 0, sizeof(curSol));
    timeUp = false;
    callCount = 0;

    // Greedy initial solution
    {
        long long rm = CAPM, rl = CAPL;
        for (int i = 0; i < n; i++) {
            long long maxByM = (items[i].m > 0) ? rm / items[i].m : (long long)items[i].q;
            long long maxByL = (items[i].l > 0) ? rl / items[i].l : (long long)items[i].q;
            int take = (int)min({(long long)items[i].q, maxByM, maxByL});
            curSol[i] = take;
            rm -= (long long)take * items[i].m;
            rl -= (long long)take * items[i].l;
            bestVal += (long long)take * items[i].v;
        }
        bestVal++; // was -1
        memcpy(bestSol, curSol, sizeof(bestSol));
        memset(curSol, 0, sizeof(curSol));
    }

    solve(0, CAPM, CAPL, 0);

    cout << "{\n";
    for (int i = 0; i < n; i++) {
        cout << " \"" << items[i].name << "\": " << bestSol[i];
        if (i < n-1) cout << ",";
        cout << "\n";
    }
    cout << "}\n";

    return 0;
}
